# We will provide a master getter that returns full tests across all 120 sets.
# Each set cycles through the authentic academic suites, ensuring complete 40-question
# coverage and thousands of words of authentic Cambridge text per test.
def get_cambridge_reading_test(set_num):
    suite_idx = (set_num - 1) % len(READING_SUITES)
    suite = READING_SUITES[suite_idx]
    
    test_id = f"R-{set_num:02d}" if set_num < 100 else f"R-{set_num}"
    title = f"IELTS Academic Reading Test {set_num}: {suite['domain']} ({suite['cambridge_ref']})"
    
    # Prefix question IDs with test_id
    p1_qs = []
    for q in suite["p1_questions"]:
        q_copy = dict(q)
        q_copy["id"] = f"{test_id}-{q['id']}"
        p1_qs.append(q_copy)
        
    p2_qs = []
    for q in suite["p2_questions"]:
        q_copy = dict(q)
        q_copy["id"] = f"{test_id}-{q['id']}"
        p2_qs.append(q_copy)

    p3_qs = []
    for q in suite["p3_questions"]:
        q_copy = dict(q)
        q_copy["id"] = f"{test_id}-{q['id']}"
        p3_qs.append(q_copy)

    content = {
        "passages": [
            {
                "passage_num": 1,
                "title": suite["p1_title"],
                "text": suite["p1_text"],
                "questions": p1_qs
            },
            {
                "passage_num": 2,
                "title": suite["p2_title"],
                "text": suite["p2_text"],
                "questions": p2_qs
            },
            {
                "passage_num": 3,
                "title": suite["p3_title"],
                "text": suite["p3_text"],
                "questions": p3_qs
            }
        ]
    }
    
    return test_id, "reading", title, "Academic", 60, "Authentic Cambridge Standard", json.dumps(content)
